var tooltipTriggerList=[].slice.call(document.querySelectorAll('[data-bs-toggle="tooltip"]')),tooltipList=tooltipTriggerList.map((function(tooltipTriggerEl){return new bootstrap.Tooltip(tooltipTriggerEl)}));function Nav(){var sidenav=document.getElementById("mySidenav"),marginRight=window.getComputedStyle(sidenav).getPropertyValue("margin-right"),btn=document.getElementById("btn-sidebar");"-350px"===marginRight||""===marginRight?(sidenav.style.marginRight="0px",btn.className=btn.className.replace("btn-sidebar-light","btn-sidebar-dark")):(sidenav.style.marginRight="-350px",btn.className=btn.className.replace("btn-sidebar-dark","btn-sidebar-light"))}function flipCard(button){var card=button.parentNode.parentNode;card.classList.contains("card-flipped")?(card.querySelector("#card_frente").classList.remove("d-none"),card.querySelector("#card_verso").classList.add("d-none"),card.classList.remove("card-flipped")):(card.querySelector("#card_verso").classList.remove("d-none"),card.querySelector("#card_frente").classList.add("d-none"),card.classList.add("card-flipped"))}var progressBar=document.getElementById("progress-bar");window.addEventListener("scroll",(function(){var scrollTop,scrollHeight,clientHeight,percent=(document.documentElement.scrollTop||document.body.scrollTop)/((document.documentElement.scrollHeight||document.body.scrollHeight)-(document.documentElement.clientHeight||window.innerHeight))*100;progressBar.style.width=percent+"%"}));